#!/usr/bin/env node
// writes public/assets/playground/spirv-grammar.js from the Khronos machine
// readable grammars: every core instruction with its operand kinds, every
// enumeration with its parameters, and the GLSL.std.450 instruction names.
// the output is committed, and this runs again only to take a newer grammar.
//
// usage: build-spirv-grammar.js <spirv.core.grammar.json> <extinst.glsl.std.450.grammar.json>
// both from https://github.com/KhronosGroup/SPIRV-Headers/tree/main/include/spirv/unified1
"use strict";

const fs = require("node:fs");
const path = require("node:path");

// an operand kind as one token: a letter for the kinds the decoder knows by
// shape, and the enumeration's own name for the rest
const SHAPES = {
  IdResultType: "T", IdResult: "R", IdRef: "I", IdMemorySemantics: "I", IdScope: "I",
  LiteralInteger: "n", LiteralString: "s", LiteralFloat: "f",
  LiteralContextDependentNumber: "c", LiteralExtInstInteger: "x", LiteralSpecConstantOpInteger: "o",
  PairLiteralIntegerIdRef: "pnI", PairIdRefLiteralInteger: "pIn", PairIdRefIdRef: "pII",
};

function operands(list) {
  return (list || []).map((o) => (SHAPES[o.kind] || o.kind) + (o.quantifier || "")).join(" ");
}

function build(core, glsl) {
  const ops = {};
  for (const inst of core.instructions) {
    if (!(inst.opcode in ops)) { ops[inst.opcode] = [inst.opname.replace(/^Op/, ""), operands(inst.operands)]; }
  }
  const enums = {};
  for (const kind of core.operand_kinds) {
    if (kind.category !== "ValueEnum" && kind.category !== "BitEnum") { continue; }
    const values = {};
    for (const e of kind.enumerants) {
      const value = Number(e.value);
      if (value in values) { continue; }
      values[value] = e.parameters ? [e.enumerant, operands(e.parameters)] : e.enumerant;
    }
    enums[kind.kind] = { bits: kind.category === "BitEnum", values };
  }
  const std450 = {};
  for (const inst of glsl.instructions) { std450[inst.opcode] = inst.opname; }
  return { version: [core.major_version, core.minor_version, core.revision].join("."), ops, enums, std450 };
}

function main() {
  const [corePath, glslPath] = process.argv.slice(2);
  if (!corePath || !glslPath) {
    console.error("usage: build-spirv-grammar.js <spirv.core.grammar.json> <extinst.glsl.std.450.grammar.json>");
    process.exit(2);
  }
  const grammar = build(JSON.parse(fs.readFileSync(corePath, "utf8")), JSON.parse(fs.readFileSync(glslPath, "utf8")));
  const out = path.resolve(__dirname, "..", "..", "public", "assets", "playground", "spirv-grammar.js");
  fs.writeFileSync(out, [
    "// generated by .github/scripts/build-spirv-grammar.js from the Khronos SPIR-V " + grammar.version + " grammar. do not edit.",
    "(function () {",
    "  var grammar = " + JSON.stringify(grammar) + ";",
    '  if (typeof module !== "undefined" && module.exports) { module.exports = grammar; } else { self.machSpirvGrammar = grammar; }',
    "})();",
    "",
  ].join("\n"));
  console.log(`built ${out}: ${Object.keys(grammar.ops).length} instructions, ${Object.keys(grammar.enums).length} enumerations`);
}

main();
